params.script:
// Extract tools from MCP response
const mcpResult = input.result;
let tools = [];

if (mcpResult && mcpResult.result && mcpResult.result.tools) {
  tools = mcpResult.result.tools;
} else if (mcpResult && mcpResult.tools) {
  tools = mcpResult.tools;
}

console.log("Available tools:", JSON.stringify(tools, null, 2));

// Check if we have a specific tool to execute from input
const targetTool = input.targetTool || input.toolName;

if (!targetTool) {
  return {
    error: "No target tool specified. Available tools: " + 
           tools.map(t => t.name).join(", "),
    availableTools: tools
  };
}

// Find the target tool
const tool = tools.find(t => t.name === targetTool);
if (!tool) {
  return {
    error: `Tool '${targetTool}' not found. Available tools: ` + 
           tools.map(t => t.name).join(", "),
    availableTools: tools
  };
}

// Prepare execution parameters
const toolParams = input.toolParameters || input.toolParams || {};

return {
  selectedTool: tool,
  toolName: tool.name,
  toolParameters: toolParams,
  availableTools: tools,
  executionReady: true
};

return {
  success: true,
  toolName: input.toolName,
  toolResult: input.result,
  availableTools: input.availableTools,
  executedAt: new Date().toISOString()
};

return {
  success: false,
  error: input.error || "Execution conditions not met",
  availableTools: input.availableTools || [],
  timestamp: new Date().toISOString()
};

return {
  success: false,
  error: "MCP operation failed: " + (input.error || "Unknown error"),
  timestamp: new Date().toISOString()
};
